'use strict';

/*
 * make-fixtures.js — builds every test input deterministically.
 * Run: node tests/make-fixtures.js
 * Output: tests/fixtures/ (regenerated byte-identically on every run)
 */

const fs = require('node:fs');
const path = require('node:path');
const { encodePNG, encodeTGA } = require('./lib/raster');

const ROOT = path.resolve(__dirname, 'fixtures');

/** Deterministic PRNG so fixtures never drift between runs. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function valueNoise2D(random, gridSize) {
  const grid = new Float32Array((gridSize + 1) * (gridSize + 1));
  for (let i = 0; i < grid.length; i++) grid[i] = random();
  const at = (x, y) => grid[(y % gridSize) * (gridSize + 1) + (x % gridSize)];
  const smooth = (t) => t * t * (3 - 2 * t);

  return function sample(u, v) {
    const gx = u * gridSize;
    const gy = v * gridSize;
    const x0 = Math.floor(gx);
    const y0 = Math.floor(gy);
    const fx = smooth(gx - x0);
    const fy = smooth(gy - y0);
    const a = at(x0, y0);
    const b = at(x0 + 1, y0);
    const c = at(x0, y0 + 1);
    const d = at(x0 + 1, y0 + 1);
    return a * (1 - fx) * (1 - fy) + b * fx * (1 - fy) + c * (1 - fx) * fy + d * fx * fy;
  };
}

function write(name, buffer) {
  const target = path.join(ROOT, name);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, buffer);
  return target;
}

/** Greyscale heightfield: stacked octaves plus a few hard-edged bumps. */
function makeHeightfield(width, height, seed) {
  const random = mulberry32(seed);
  const octaves = [
    { grid: 4, weight: 0.5 },
    { grid: 8, weight: 0.25 },
    { grid: 16, weight: 0.15 },
    { grid: 32, weight: 0.1 }
  ].map((o) => ({ weight: o.weight, sample: valueNoise2D(random, o.grid) }));

  const data = Buffer.alloc(width * height);
  const bumps = [
    { cx: 0.28, cy: 0.3, r: 0.16, h: 0.85 },
    { cx: 0.72, cy: 0.34, r: 0.12, h: 0.7 },
    { cx: 0.5, cy: 0.72, r: 0.2, h: 0.95 },
    { cx: 0.16, cy: 0.8, r: 0.09, h: 0.6 }
  ];

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const u = x / width;
      const v = y / height;
      let value = 0;
      for (const octave of octaves) value += octave.sample(u, v) * octave.weight;

      for (const bump of bumps) {
        const dx = u - bump.cx;
        const dy = v - bump.cy;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < bump.r) {
          const falloff = 1 - dist / bump.r;
          value += bump.h * falloff * falloff * (3 - 2 * falloff);
        }
      }

      // A hard step across the middle exercises edge handling.
      if (u > 0.46 && u < 0.54) value += 0.25;

      data[y * width + x] = Math.max(0, Math.min(255, Math.round(value * 165)));
    }
  }
  return data;
}

function makeColorField(width, height, seed) {
  const random = mulberry32(seed);
  const n = valueNoise2D(random, 8);
  const data = Buffer.alloc(width * height * 3);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const u = x / width;
      const v = y / height;
      const base = n(u, v);
      const i = (y * width + x) * 3;
      data[i] = Math.round(255 * Math.min(1, base * 1.4 + u * 0.4));
      data[i + 1] = Math.round(255 * Math.min(1, (1 - base) * 1.1 + v * 0.3));
      data[i + 2] = Math.round(255 * (0.25 + 0.7 * Math.abs(Math.sin(u * 9 + v * 5))));
    }
  }
  return data;
}

function makeAlphaField(width, height, seed) {
  const gray = makeHeightfield(width, height, seed);
  const data = Buffer.alloc(width * height * 4);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = y * width + x;
      data[i * 4] = gray[i];
      data[i * 4 + 1] = gray[i];
      data[i * 4 + 2] = gray[i];
      // Transparent left edge, opaque right edge.
      data[i * 4 + 3] = Math.round(255 * (0.15 + 0.85 * (x / (width - 1))));
    }
  }
  return data;
}

function makeObj() {
  // Pyramid with explicit normals; small enough to read, real enough to load.
  const lines = ['# NormalMap Desktop test model', '# pyramid, 5 vertices'];
  const v = [
    [0, 1, 0],
    [-1, -0.5, 1],
    [1, -0.5, 1],
    [1, -0.5, -1],
    [-1, -0.5, -1]
  ];
  v.forEach((p) => lines.push(`v ${p[0]} ${p[1]} ${p[2]}`));
  lines.push('vn 0 0.7071 0.7071');
  lines.push('vn 0.7071 0.7071 0');
  lines.push('vn 0 0.7071 -0.7071');
  lines.push('vn -0.7071 0.7071 0');
  lines.push('vn 0 -1 0');
  lines.push('f 1//1 2//1 3//1');
  lines.push('f 1//2 3//2 4//2');
  lines.push('f 1//3 4//3 5//3');
  lines.push('f 1//4 5//4 2//4');
  lines.push('f 2//5 5//5 4//5 3//5');
  return Buffer.from(lines.join('\n') + '\n', 'utf8');
}

function main() {
  fs.rmSync(ROOT, { recursive: true, force: true });
  fs.mkdirSync(ROOT, { recursive: true });

  const created = [];

  const gray256 = makeHeightfield(256, 256, 20261114);
  created.push(write('height-bumps-256.png', encodePNG({ width: 256, height: 256, channels: 1, data: gray256 })));

  const color256 = makeColorField(256, 256, 777);
  created.push(write('basecolor-color-256.png', encodePNG({ width: 256, height: 256, channels: 3, data: color256 })));

  const alpha192 = makeAlphaField(192, 192, 4242);
  created.push(write('height-alpha-192.png', encodePNG({ width: 192, height: 192, channels: 4, data: alpha192 })));

  const wide = makeHeightfield(300, 200, 31337);
  created.push(write('height-300x200.png', encodePNG({ width: 300, height: 200, channels: 1, data: wide })));

  const odd = makeHeightfield(255, 257, 5150);
  created.push(write('height-255x257.png', encodePNG({ width: 255, height: 257, channels: 1, data: odd })));

  const large = makeHeightfield(2048, 2048, 90210);
  created.push(write('height-large-2048.png', encodePNG({ width: 2048, height: 2048, channels: 1, data: large })));

  const tga = makeHeightfield(128, 128, 6161);
  const tgaRGB = Buffer.alloc(128 * 128 * 3);
  for (let i = 0; i < 128 * 128; i++) {
    tgaRGB[i * 3] = tga[i];
    tgaRGB[i * 3 + 1] = tga[i];
    tgaRGB[i * 3 + 2] = tga[i];
  }
  created.push(write('height-tga-128.tga', encodeTGA({ width: 128, height: 128, channels: 3, data: tgaRGB })));

  // Same file name, different content, different folders: catches cross-talk.
  const a = makeHeightfield(160, 160, 111);
  const b = makeHeightfield(160, 160, 999);
  created.push(write('batch/dirA/pattern.png', encodePNG({ width: 160, height: 160, channels: 1, data: a })));
  created.push(write('batch/dirB/pattern.png', encodePNG({ width: 160, height: 160, channels: 1, data: b })));

  // A file that claims to be a PNG but is not: the save path must reject
  // nothing here, the *import* path must.
  created.push(write('not-an-image.png', Buffer.from('this is not a png', 'utf8')));

  created.push(write('model-pyramid.obj', makeObj()));

  // Real four-direction photographs. Origin: the four bundled example photos
  // shipped with NormalMap-Online (Christian Petry's own bath-rug captures).
  const photoSrc = path.resolve(__dirname, '..', 'renderer', 'images');
  const photoNames = ['above', 'left', 'right', 'below'];
  for (const dir of photoNames) {
    const from = path.join(photoSrc, `default_picture_${dir}.jpg`);
    const to = path.join(ROOT, 'photos', `rug-${dir}.jpg`);
    fs.mkdirSync(path.dirname(to), { recursive: true });
    fs.copyFileSync(from, to);
    created.push(to);
  }

  // Diffuse texture for the preview material.
  const diffuse = makeColorField(256, 256, 8080);
  created.push(write('diffuse-256.png', encodePNG({ width: 256, height: 256, channels: 3, data: diffuse })));

  console.log(`Created ${created.length} fixtures in ${ROOT}`);
  created.forEach((p) => console.log('  ' + path.relative(ROOT, p)));
}

if (require.main === module) main();

module.exports = { makeHeightfield, makeColorField, mulberry32 };
